"""Hadamard transforms used by QuaRot.

The upstream file also credits quip-sharp for ``matmul_had.py``.
"""

from __future__ import annotations

import math

import torch

_FALLBACK_CACHE: dict[tuple[int, str], torch.Tensor] = {}


def _sylvester(size: int, device: torch.device | str) -> torch.Tensor:
    matrix = torch.tensor([[1.0]], device=device, dtype=torch.float32)
    while matrix.shape[0] < size:
        matrix = torch.cat(
            [
                torch.cat([matrix, matrix], dim=1),
                torch.cat([matrix, -matrix], dim=1),
            ],
            dim=0,
        )
    return matrix / math.sqrt(size)


def _fallback_hadamard(size: int, device: torch.device | str) -> torch.Tensor:
    """Kronecker(random orthogonal odd factor, Sylvester power-of-two factor).

    QuaRot's fast transform only supports a fixed list of odd factors, so
    fall back to a dense orthogonal matrix for any other size.  The matrix is deterministic and cached.
    """
    key = (size, str(device))
    cached = _FALLBACK_CACHE.get(key)
    if cached is not None:
        return cached
    block = 1
    while size % (2 * block) == 0:
        block *= 2
    odd = size // block
    generator = torch.Generator(device=device)
    generator.manual_seed(0)
    random = torch.randn(
        odd,
        odd,
        device=device,
        dtype=torch.float64,
        generator=generator,
    )
    orthogonal, triangular = torch.linalg.qr(random)
    orthogonal *= torch.sign(torch.diag(triangular)).unsqueeze(0)
    matrix = torch.kron(
        orthogonal.float().contiguous(),
        _sylvester(block, device).contiguous(),
    ).contiguous()
    _FALLBACK_CACHE[key] = matrix
    return matrix


def get_hadK(n, transpose=False):
    hadK, K = None, None
    if n % 172 == 0:  # llama-2-7b up
        assert is_pow2(n // 172)
        K = 172
        hadK = get_had172().T if transpose else get_had172()
    elif n % 156 == 0:  # llama-1-30b 3x hidden
        assert is_pow2(n // 156)
        K = 156
        hadK = get_had156().T if transpose else get_had156()
    elif n % 140 == 0:  # llama-1-30b intermediate
        assert is_pow2(n // 140)
        K = 140
        hadK = get_had140().T if transpose else get_had140()
    elif n % 108 == 0:  # llama-1-13b intermediate
        assert is_pow2(n // 108)
        K = 108
        hadK = get_had108().T if transpose else get_had108()
    elif n % 60 == 0:  # llama-1-13b 3x hidden
        assert is_pow2(n // 60)
        K = 60
        hadK = get_had60().T if transpose else get_had60()
    elif n % 52 == 0:  # llama-1-13b 1x hidden
        assert is_pow2(n // 52)
        K = 52
        hadK = get_had52().T if transpose else get_had52()
    elif n % 36 == 0:
        assert is_pow2(n // 36)
        K = 36
        hadK = get_had36().T if transpose else get_had36()
    elif n % 28 == 0:
        assert is_pow2(n // 28)
        K = 28
        hadK = get_had28().T if transpose else get_had28()
    elif n % 40 == 0:
        assert is_pow2(n // 40)
        K = 40
        hadK = get_had40().T if transpose else get_had40()
    elif n % 20 == 0:
        assert is_pow2(n // 20)
        K = 20
        hadK = get_had20().T if transpose else get_had20()
    elif n % 12 == 0:
        assert is_pow2(n // 12)
        K = 12
        hadK = get_had12().T if transpose else get_had12()
    else:
        assert is_pow2(n)
        K = 1

    return hadK, K


def matmul_hadU(X, transpose=False):
    n = X.shape[-1]
    try:
        hadK, K = get_hadK(n, transpose)
    except AssertionError:
        matrix = _fallback_hadamard(n, X.device)
        if transpose:
            matrix = matrix.t()
        dtype = X.dtype
        result = X.reshape(-1, n).float() @ matrix
        return result.to(dtype).reshape(X.shape)
    input = X.clone().reshape(-1, n, 1)
    output = input.clone()
    while input.shape[1] > K:
        input = input.view(input.shape[0], input.shape[1] // 2, 2, input.shape[2])
        output = output.view(input.shape)
        output[:, :, 0, :] = input[:, :, 0, :] + input[:, :, 1, :]
        output[:, :, 1, :] = input[:, :, 0, :] - input[:, :, 1, :]
        output = output.view(input.shape[0], input.shape[1], -1)
        (input, output) = (output, input)
    del output

    if K > 1:
        # Do not explicitly repeat - OOM
        # input = torch.bmm(
        #     hadK.repeat(len(input), 1, 1).to(input.device).to(input.dtype), input)
        # Use bcast instead
        input = hadK.view(1, K, K).to(input) @ input

    return input.view(X.shape) / (n**0.5)


def random_hadamard_matrix(size, device):
    # See https://cornell-relaxml.github.io/quip-sharp/ , Section "Randomized Hadamard Transformation"
    Q = torch.randint(low=0, high=2, size=(size,)).to(torch.float64)
    Q = Q * 2 - 1
    Q = torch.diag(Q)
    return matmul_hadU(Q).to(device)


def apply_exact_had_to_linear(
    module: torch.nn.Linear,
    had_dim: int = -1,
    output: bool = False,
) -> None:
    """Apply an exact Hadamard transform to a linear layer in place."""
    if had_dim != -1:
        assert is_pow2(had_dim), "Hadamard dimension must be a power of 2!"

    weight = module.weight.data
    dtype = weight.dtype
    device = weight.device
    work = weight.float()

    if had_dim == -1:
        if output:
            work = matmul_hadU(work.t()).t()
        else:
            work = matmul_hadU(work)
    elif output:
        work = work.t().contiguous()
        transposed_shape = work.shape
        chunks = work.reshape(
            -1,
            transposed_shape[-1] // had_dim,
            had_dim,
        ).contiguous()
        work = matmul_hadU(chunks).reshape(transposed_shape).t()
    else:
        shape = work.shape
        if shape[1] % had_dim != 0:
            raise ValueError("input dimension is not divisible by had_dim")
        chunks = work.reshape(
            shape[0],
            shape[1] // had_dim,
            had_dim,
        ).contiguous()
        work = matmul_hadU(chunks).reshape(shape)

    module.weight.data = work.to(device=device, dtype=dtype)

    if output and module.bias is not None:
        # Output-side Hadamard must also rotate the bias (Llama-2 itself has
        # no projection biases).
        bias = module.bias.data.float().reshape(1, -1)
        if had_dim != -1:
            bias = bias.reshape(-1, had_dim)
        bias = matmul_hadU(bias).reshape(-1)
        module.bias.data = bias.to(device=device, dtype=dtype)


def is_pow2(n):
    return (n & (n - 1) == 0) and (n > 0)


